    amount numeric(10,2) NOT NULL,
    type character varying(32) NOT NULL,
    reference_id uuid,
    description character varying(500),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_ledger_amount_sign CHECK (
CASE
    WHEN ((type)::text = ANY ((ARRAY['BOOKING_DEDUCTION'::character varying, 'CASH_OUT_DEBIT'::character varying, 'STRIPE_FEE_DEBIT'::character varying])::text[])) THEN (amount < (0)::numeric)
    ELSE (amount > (0)::numeric)
END),
    CONSTRAINT chk_ledger_type CHECK (((type)::text = ANY ((ARRAY['BOOKING_DEDUCTION'::character varying, 'BOOKING_DEDUCTION_REVERSAL'::character varying, 'BOOKING_REFUND'::character varying, 'CASH_OUT_DEBIT'::character varying, 'STRIPE_FEE_DEBIT'::character varying, 'CASH_OUT_REVERSAL'::character varying])::text[])))
);

--
-- Name: parent_credit_balance; Type: VIEW; Schema: payment; Owner: -
--

CREATE VIEW payment.parent_credit_balance AS
 SELECT parent_id,
    COALESCE(sum(amount), (0)::numeric) AS balance
   FROM payment.parent_credit_ledger
  GROUP BY parent_id;

